'use strict';
// Needs, physical labor and shelter share one planner; animation never grants resources.
const livingOld={resident:planResident,animal:planAnimal,simulate,ecology,newWorld,restore,snapshot,spawn,drawCreature,draw,selection:showSelection,onDuty:isOnDuty};
const lifeActions=['fish','craft','idle','walk','chop','carry','harvest','plant','build','mine','sleep','rest','graze','drink','hunt','flee','social','learn','forage'];
Object.assign(purposeNames,{fish:'Đánh cá',craft:'Rèn dụng cụ',chop:'Chặt cây',carry:'Mang vật liệu về kho',harvest:'Thu hoạch',plant:'Gieo trồng',build:'Xây nhà',learn:'Học từ người lớn',drink:'Uống nước',den:'Về nơi nghỉ',forage:'Hái quả'});
let livingTick=0,homeTick=0,regrowTick=0,regrowingTrees=new Map(),footTraffic=new Map(),lastFootTile=new WeakMap();
function lifeFor(e){if(!e.life)e.life={homeId:null,inside:false,loadType:null,load:0,action:'idle',targetIndex:-1,progress:0,skill:0,thirst:80,energy:85,parentId:null,den:{x:e.x,y:e.y}};return e.life;}
function residentHome(e){const id=lifeFor(e).homeId;return houses.find(h=>h.id===id&&h.village===e.village&&h.hp>0);}
function homeDoor(h){return{x:h.x,y:h.y+.22};}
function isResidentIndoors(e){if(e.kind!=='human'||e.id===possessed||!e.life?.inside)return false;const h=residentHome(e);return !!h&&Math.hypot(e.x-h.x,e.y-h.y)<.6&&!grid[idx(h.x,h.y)].fire;}
function assignHomes(){const assigned=new Map();for(const e of humans()){const l=lifeFor(e),h=residentHome(e);if(h&&(assigned.get(h.id)||0)<3){assigned.set(h.id,(assigned.get(h.id)||0)+1);continue;}l.homeId=null;l.inside=false;}for(const e of humans()){const l=lifeFor(e);if(l.homeId!==null)continue;const homes=houses.filter(h=>h.village===e.village&&h.hp>0&&(assigned.get(h.id)||0)<3).sort((a,b)=>Math.hypot(a.x-e.x,a.y-e.y)-Math.hypot(b.x-e.x,b.y-e.y));const h=homes.find(h=>walkable(h.x,h.y)&&!grid[idx(h.x,h.y)].fire&&(clearRoute(e,homeDoor(h))||pathStep(e,homeDoor(h),false)));if(h){l.homeId=h.id;assigned.set(h.id,(assigned.get(h.id)||0)+1);}}}
function leaveHome(e){lifeFor(e).inside=false;}
function enterHome(e,h,action='sleep'){const l=lifeFor(e),door=homeDoor(h);e.sailing=false;if(Math.hypot(e.x-door.x,e.y-door.y)>.32){l.inside=false;l.action='walk';go(e,door,'home',30);return;}stop(e,'home');motionFor(e).vx=motionFor(e).vy=0;e.x=e.tx=door.x;e.y=e.ty=door.y;l.inside=true;l.action=action;}
function mayEatAtTile(e,t){return !isResidentIndoors(e)&&!['sleep','flee','chop','build','carry'].includes(lifeFor(e).action)&&(t.obj===3||t.t===5)&&e.hunger<78;}
function mayGraze(e){return mindFor(e).type==='graze'&&Math.hypot(motionFor(e).vx,motionFor(e).vy)<.12&&!grid[idx(e.x,e.y)].fire;}
function humanFoodTile(t){return(t.obj===3||t.t===5)&&t.food>2&&!t.fire;}
function workStand(e,target){const options=[{x:target.x-.7,y:target.y+.3},{x:target.x+.7,y:target.y+.3},{x:target.x,y:target.y+.7}];return options.find(p=>walkable(p.x,p.y)&&!grid[idx(p.x,p.y)].fire&&(clearRoute(e,p)||pathStep(e,p,false)));}
function taskMove(e,target,type){const l=lifeFor(e);if(Math.hypot(e.x-target.x,e.y-target.y)>.35){l.action='walk';go(e,target,type,25);return false;}stop(e,type);motionFor(e).vx=motionFor(e).vy=0;l.action=type;return true;}
function bringLoadHome(e,v){const l=lifeFor(e);if(!v)return false;if(Math.hypot(e.x-v.x,e.y-v.y)>1.8){l.action='carry';go(e,v,'carry',30);return true;}if(l.loadType==='wood')v.wood=Math.min(500,v.wood+l.load);else if(l.loadType==='food')v.food=Math.min(10000,v.food+l.load);v.production+=l.load;v.knowledge=Math.min(2000,v.knowledge+.015*l.load);l.load=0;l.loadType=null;l.targetIndex=-1;l.progress=0;stop(e,'work');return true;}
function laborPlan(e,v){const l=lifeFor(e);if(l.load>0&&!((l.action==='harvest'&&grid[l.targetIndex]?.food>.1||l.action==='fish')&&l.load<7.9))return bringLoadHome(e,v);if(e.age<16||!v)return false;
 if(e.job==='builder'&&v.housePlan){const plan=v.housePlan;l.targetIndex=idx(plan.x,plan.y);taskMove(e,{x:plan.x,y:plan.y+.25},'build');return true;}
 if(e.job==='smith'){const forge=buildings.find(b=>b.village===v.id&&b.kind==='forge');if(forge){taskMove(e,{x:forge.x+.7,y:forge.y+.5},'craft');return true;}}
 if(e.job==='lumberjack'){let i=l.targetIndex;if(i<0||![0,1].includes(grid[i]?.obj)||grid[i].fire){const target=nearestTile(e,t=>[0,1].includes(t.obj)&&!t.fire,18);if(!target)return false;i=idx(target.x,target.y);l.targetIndex=i;l.progress=0;}const point={x:i%W+.5,y:Math.floor(i/W)+.5},stand=workStand(e,point);if(!stand){l.targetIndex=-1;return false;}if(taskMove(e,stand,'chop'))motionFor(e).facing=point.x>=e.x?1:-1;return true;}
 if(e.job==='farmer'){if(l.loadType==='food'&&l.load>0&&grid[l.targetIndex]?.t===5&&grid[l.targetIndex].food>.1){taskMove(e,{x:l.targetIndex%W+.5,y:Math.floor(l.targetIndex/W)+.5},'harvest');return true;}if(v.farmPlan){const plan=v.farmPlan;l.targetIndex=idx(plan.x,plan.y);taskMove(e,plan,'plant');return true;}let i=l.targetIndex;if(i<0||grid[i]?.t!==5||grid[i].food<8){const field=nearestTile(e,t=>t.t===5&&t.food>=8&&!t.fire,16);if(!field){const fishery=buildings.find(b=>b.village===v.id&&b.kind==='fishery');if(!fishery)return false;taskMove(e,{x:fishery.x+.7,y:fishery.y+.5},'fish');return true;}i=idx(field.x,field.y);l.targetIndex=i;}taskMove(e,{x:i%W+.5,y:Math.floor(i/W)+.5},'harvest');return true;}
 return false;}
planResident=function(e){if(e.id===possessed){leaveHome(e);return;}const l=lifeFor(e),m=mindFor(e),v=villages.find(v=>v.id===e.village),h=residentHome(e),hour=readCalendar().hour;const fire=laws.disasters?burningNear(e):null;const enemy=around(e,5,p=>hungryPredator(p)&&suitablePrey(p,e)||p.kind==='human'&&atWar(kingdomOf(e),kingdomOf(p)))[0];
 if(!fire&&enemy&&isResidentIndoors(e)){enterHome(e,h,l.action==='sleep'?'sleep':'rest');return;}
 if(fire||enemy){leaveHome(e);l.action='flee';if(fire)escapeDanger(e,fire);else livingOld.resident(e);return;}
 if(e.hunger<45||m.type==='food'&&e.hunger<78){leaveHome(e);l.action='forage';if(v?.food>0){go(e,v,'food',20);return;}const food=nearestTile(e,humanFoodTile,18);if(food)go(e,food,'forage',20);else stop(e,'forage');return;}
 if(e.thirst<35||m.type==='water'&&e.thirst<70){leaveHome(e);l.action='drink';livingOld.resident(e);return;}
 const night=hour>=20||hour<6,weather=weatherAt(e.x,e.y);if(!e.soldier&&(night||e.energy<18||e.hp<40||['storm','snow'].includes(weather)&&e.talent!=='frost')){if(h){enterHome(e,h,night?'sleep':'rest');return;}leaveHome(e);l.action=night?'sleep':'rest';pauseAnimal(e,'rest',3);return;}
 leaveHome(e);if(e.cargo&&v){l.action='carry';if(Math.hypot(e.x-v.x,e.y-v.y)<2.5){depositCargo(e,v);stop(e,'carry');}else go(e,v,'carry',30);return;}if(e.age<16){livingOld.resident(e);l.action='learn';const adult=around(e,3,p=>p.kind==='human'&&p.village===e.village&&p.age>=16)[0];if(adult&&e.age>=2){l.skill=Math.min(100,l.skill+.002);if(['chop','harvest','plant'].includes(lifeFor(adult).action)){go(e,{x:adult.x+.8,y:adult.y+.5},'learn',10);return;}}return;}
 if(e.soldier){l.action='walk';livingOld.resident(e);return;}
 e.activity='working';if(laborPlan(e,v))return;livingOld.resident(e);l.action=m.type==='social'?'social':m.type==='work'&&e.job==='miner'&&Math.hypot(motionFor(e).vx,motionFor(e).vy)<.12?'mine':'walk';};
// MODIFIED v12: family homes, spare nursery space, larger settlement footprint.
function lifeHousing(v,pop,hs){hs=hs.filter(h=>h.hp>0);if(v.housePlan||!v.autoBuild||hs.length>=80||pop<1||pop<hs.length*2||!humans().some(e=>e.village===v.id&&e.age>=16))return;if(v.wood<8||v.food<12||v.stock.stone<4)return;for(let k=0;k<192;k++){const a=k*Math.PI/8,r=4+Math.floor(k/16)*2,p=findLand(v.x+Math.cos(a)*r,v.y+Math.sin(a)*r);if(!p||Math.hypot(p.x-v.x,p.y-v.y)>28||grid[idx(p.x,p.y)].fire||houses.some(h=>h.hp>0&&Math.hypot(h.x-p.x,h.y-p.y)<3)||buildings.some(b=>Math.hypot(b.x-p.x,b.y-p.y)<2))continue;v.wood-=8;v.food-=12;v.stock.stone-=4;v.housePlan={x:p.x,y:p.y,progress:0};return;}}

function planFarmExpansion(v){if(v.farmPlan||v.wood<2||grid.some((t,i)=>t.t===5&&Math.hypot(i%W-v.x,Math.floor(i/W)-v.y)<10)||!humans().some(e=>e.village===v.id&&e.job==='farmer'&&e.age>=16))return;for(let y=Math.max(0,Math.floor(v.y-4));y<Math.min(H,v.y+5);y++)for(let x=Math.max(0,Math.floor(v.x-4));x<Math.min(W,v.x+5);x++)if(grid[idx(x,y)].t===1&&grid[idx(x,y)].obj===-1&&!grid[idx(x,y)].fire&&houses.every(h=>Math.hypot(h.x-x-.5,h.y-y-.5)>1.7)){v.farmPlan={x:x+.5,y:y+.5,progress:0};v.wood-=2;return;}}
function residentLaborStep(e,dt){const l=lifeFor(e),v=villages.find(v=>v.id===e.village);if(!v||e.age<16||e.id===possessed||e.hunger<45||e.thirst<35||!isOnDuty(e)||Math.hypot(motionFor(e).vx,motionFor(e).vy)>.12)return;const rate=dt*(.8+l.skill/200)*(e.energy<35?.6:1),t=grid[l.targetIndex];
 if(l.action==='chop'&&t&&[0,1].includes(t.obj)&&!t.fire){const point={x:l.targetIndex%W+.5,y:Math.floor(l.targetIndex/W)+.5};if(Math.hypot(e.x-point.x,e.y-point.y)>1.3)return;t.treeWork=Math.min(1,(t.treeWork||0)+rate*(e.equipment.tool?1.5:1)/12);l.progress=t.treeWork;if(t.treeWork>=1){Object.assign(t,{obj:-1,t:1,food:Math.min(6,t.food),treeWork:0,treeRegrowAt:simTime+GAME_DAY_SECONDS*2});regrowingTrees.set(l.targetIndex,t.treeRegrowAt);l.loadType='wood';l.load=4+(e.equipment.tool?2:0);l.action='carry';l.progress=0;mapDirty=true;biomeEpoch=-1;v.knowledge=Math.min(2000,v.knowledge+.06);}l.skill=Math.min(100,l.skill+dt*.015);}
 else if(l.action==='fish'&&buildings.some(b=>b.village===v.id&&b.kind==='fishery'&&Math.hypot(b.x-e.x,b.y-e.y)<2&&hasWaterNear(b.x,b.y,6))){l.loadType='food';l.load=Math.min(8,l.load+rate*.8);l.skill=Math.min(100,l.skill+dt*.01);if(l.load>=7.9)l.action='carry';}
 else if(l.action==='harvest'&&t?.t===5&&t.food>0&&idx(e.x,e.y)===l.targetIndex){const amount=Math.min(t.food,rate*1.2,8-l.load);t.food-=amount;l.load+=amount;l.loadType='food';l.skill=Math.min(100,l.skill+dt*.01);if(l.load>=7.9||t.food<.1){l.action='carry';l.targetIndex=-1;}}
 else if(l.action==='plant'&&v.farmPlan&&Math.hypot(e.x-v.farmPlan.x,e.y-v.farmPlan.y)<.5){v.farmPlan.progress=Math.min(1,v.farmPlan.progress+rate/8);l.progress=v.farmPlan.progress;if(v.farmPlan.progress>=1){const i=idx(v.farmPlan.x,v.farmPlan.y);if(grid[i].t===1&&!grid[i].fire){Object.assign(grid[i],{t:5,obj:11,food:0});mapDirty=true;remember(v.name+' gieo một ruộng lúa mới.','civil');}v.farmPlan=null;l.progress=0;l.targetIndex=-1;}}
 else if(l.action==='build'&&v.housePlan&&Math.hypot(e.x-v.housePlan.x,e.y-v.housePlan.y)<.7){const plan=v.housePlan;plan.progress=Math.min(1,plan.progress+rate/24);l.progress=plan.progress;if(plan.progress>=1){if(walkable(plan.x,plan.y)&&!grid[idx(plan.x,plan.y)].fire){houses.push({id:idCounter++,x:plan.x,y:plan.y,village:v.id,level:0,hp:100});grid[idx(plan.x,plan.y)].obj=-1;remember(v.name+' hoàn thành một ngôi nhà.','civil');mapDirty=true;}v.housePlan=null;l.progress=0;assignHomes();}}
}
isOnDuty=e=>e.age>=16&&!isResidentIndoors(e)&&livingOld.onDuty(e)&&!['sleep','rest','drink','forage','learn','flee'].includes(lifeFor(e).action);
function animalWater(e){return nearestTile(e,(t,x,y)=>!t.fire&&[[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy])=>inside(x+dx,y+dy)&&grid[idx(x+dx,y+dy)].t===0),14);}
function suitablePrey(hunter,prey){if(prey.kind==='human')return hunter.hunger<20&&!prey.soldier&&!isResidentIndoors(prey);if(prey.kind!=='sheep')return false;if(hunter.species==='allosaur')return true;if(!prey.species)return true;if(hunter.species==='saber'&&prey.species==='mammoth')return prey.hp<55||around(hunter,6,p=>p.species==='saber').length>=2;return prey.hp<40;}
planAnimal=function(e){const l=lifeFor(e),m=mindFor(e);if(e.id===possessed)return;const fire=laws.disasters?burningNear(e):null,threat=e.kind==='sheep'?around(e,7,p=>hungryPredator(p)&&suitablePrey(p,e))[0]:null;if(fire||threat){l.action='flee';escapeDanger(e,fire||threat);return;}
 if(l.thirst<35||m.type==='drink'&&l.thirst<85){let target=m.type==='drink'&&m.goal?m.goal:animalWater(e);if(target){if(taskMove(e,target,'drink'))l.action='drink';return;}}
 if(e.kind==='wolf'){if(m.prey){const prey=entities.find(p=>p.id===m.prey);if(prey&&!suitablePrey(e,prey)){m.prey=null;m.preyRetry=simTime+4;stop(e,'rest');}}if(hungryPredator(e)&&!m.prey){const pack=around(e,7,p=>p.kind==='wolf'&&(p.species||'wolf')===(e.species||'wolf')&&mindFor(p).prey).find(p=>{const prey=entities.find(q=>q.id===mindFor(p).prey);return prey&&suitablePrey(e,prey);});if(pack){m.prey=mindFor(pack).prey;m.huntUntil=simTime+20;}}}
 const parent=entities.find(p=>p.id===l.parentId&&p.hp>0);if(e.age<1&&parent&&e.hunger>45&&Math.hypot(e.x-parent.x,e.y-parent.y)>2){l.action='walk';go(e,parent,'parent',12);return;}
 livingOld.animal(e);if(e.kind==='wolf'&&m.prey){const prey=entities.find(p=>p.id===m.prey);if(prey&&!suitablePrey(e,prey)){m.prey=null;m.preyRetry=simTime+5;pauseAnimal(e,'rest',3);}}
 if(['sleep','rest'].includes(m.type)&&e.hunger>55&&l.energy<95){const shelter=nearestTile(e,t=>[0,1,3].includes(t.obj)&&!t.fire,8)||l.den;if(Math.hypot(e.x-shelter.x,e.y-shelter.y)>1.5&&clearRoute(e,shelter)){go(e,shelter,'den',15);l.action='walk';return;}}l.action=m.type==='graze'?'graze':m.type==='hunt'?'hunt':m.type==='sleep'?'sleep':m.type==='rest'?'rest':'walk';};
function registerAnimalBirth(parent,child){if(child){lifeFor(child).parentId=parent.id;child.age=0;}}
spawn=function(...args){const e=livingOld.spawn(...args);if(e){lifeFor(e);if(e.kind!=='human'&&!birthContext)e.age=2+e.id%5;}return e;};
function updateLiving(dt){const hour=readCalendar().hour;for(const e of entities){const l=lifeFor(e);if(e.kind==='human'){if(isResidentIndoors(e)){e.energy=Math.min(100,e.energy+dt*(l.action==='sleep'?.16:.07));e.hp=Math.min(100,e.hp+dt*.025);}else if(e.energy!==undefined)e.energy=Math.max(0,e.energy-dt*(['chop','harvest','build','mine'].includes(l.action)?.05:.018));residentLaborStep(e,dt);}else{l.thirst=Math.max(0,l.thirst-dt*(l.action==='sleep'?.012:.035));l.energy=limit(l.energy+dt*(['sleep','rest'].includes(l.action)?.15:-.025),0,100);if(l.action==='drink'&&Math.hypot(motionFor(e).vx,motionFor(e).vy)<.12)l.thirst=Math.min(100,l.thirst+dt*6);if(l.thirst<=0)damage(e,dt*.35);if(['mammoth','triceratops'].includes(e.species)){const attacker=around(e,1.5,p=>hungryPredator(p)&&mindFor(p).prey===e.id)[0];if(attacker&&e.hp>35&&simTime>=(mindFor(e).defendAt||0)){damage(attacker,9);mindFor(e).defendAt=simTime+2;}}}}
 homeTick+=dt;livingTick+=dt;regrowTick+=dt;if(homeTick>=2){homeTick%=2;assignHomes();}if(livingTick>=1){livingTick%=1;for(const v of villages){if(v.housePlan&&(!walkable(v.housePlan.x,v.housePlan.y)||grid[idx(v.housePlan.x,v.housePlan.y)].fire)){v.wood+=8;v.food+=12;v.stock.stone+=4;v.housePlan=null;}if(v.farmPlan&&grid[idx(v.farmPlan.x,v.farmPlan.y)].t!==1){v.wood+=2;v.farmPlan=null;}planFarmExpansion(v);}steerWorkers();}if(regrowTick>=10){regrowTick%=10;for(const [i,time] of regrowingTrees){const t=grid[i];if(t.treeRegrowAt!==time){regrowingTrees.delete(i);continue;}if(simTime<time)continue;if(t.t===1&&t.obj===-1&&!t.fire&&houses.every(h=>Math.hypot(h.x-i%W-.5,h.y-Math.floor(i/W)-.5)>2)&&buildings.every(b=>Math.hypot(b.x-i%W-.5,b.y-Math.floor(i/W)-.5)>2)){Object.assign(t,{t:3,obj:i%2,food:12,treeWork:0});mapDirty=true;biomeEpoch=-1;}delete t.treeRegrowAt;regrowingTrees.delete(i);}}}
simulate=function(dt){livingOld.simulate(dt);updateLiving(dt);};
function resetLiving(plan=true){livingTick=homeTick=regrowTick=0;footTraffic.clear();lastFootTile=new WeakMap();regrowingTrees=new Map();for(let i=0;i<N;i++)if(grid[i].treeRegrowAt)regrowingTrees.set(i,grid[i].treeRegrowAt);for(const e of entities)lifeFor(e);assignHomes();if(plan)steerWorkers();}
newWorld=function(...args){livingOld.newWorld(...args);resetLiving();};
snapshot=function(){const d=JSON.parse(JSON.stringify(livingOld.snapshot()));d.version=9;const ids=new Set(d.houses.map(h=>h.id));for(const e of d.entities)if(e.life&&!ids.has(e.life.homeId)){e.life.homeId=null;e.life.inside=false;}return d;};
function validateLiving(d){const finite=(n,max)=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=max;const validPlan=p=>p===undefined||p===null||finite(p.x,W-.001)&&finite(p.y,H-.001)&&finite(p.progress,1);if(!d.grid.every(t=>(t.treeWork===undefined||finite(t.treeWork,1))&&(t.treeRegrowAt===undefined||finite(t.treeRegrowAt,1e9)))||!d.villages.every(v=>validPlan(v.housePlan)&&validPlan(v.farmPlan))||!d.entities.every(e=>{const l=e.life;return l&&[null,...d.houses.map(h=>h.id)].includes(l.homeId)&&typeof l.inside==='boolean'&&(l.loadType===null||['wood','food'].includes(l.loadType))&&finite(l.load,20)&&lifeActions.includes(l.action)&&Number.isInteger(l.targetIndex)&&l.targetIndex>=-1&&l.targetIndex<N&&finite(l.progress,1)&&finite(l.skill,100)&&finite(l.thirst,100)&&finite(l.energy,100)&&(l.parentId===null||Number.isInteger(l.parentId)&&l.parentId>0)&&l.den&&finite(l.den.x,W-.001)&&finite(l.den.y,H-.001);}))throw Error('Dữ liệu sinh hoạt không hợp lệ.');}
restore=function(input){const d=JSON.parse(JSON.stringify(input));if(!d||!Array.isArray(d.entities)||!Array.isArray(d.grid)||!Array.isArray(d.houses)||!Array.isArray(d.villages))throw Error('Tệp thế giới không hợp lệ.');if(d.version===9){validateLiving(d);d.version=8;}else{for(const e of d.entities)delete e.life;for(const t of d.grid){delete t.treeWork;delete t.treeRegrowAt;}for(const v of d.villages){delete v.housePlan;delete v.farmPlan;}}livingOld.restore(d);resetLiving(false);};
// Visual state is separate from simulation and save data.
const creatureAnimation=new WeakMap();
function animationPose(e){const now=animationTime(),m=motionFor(e),l=lifeFor(e);let p=creatureAnimation.get(e);if(!p){p={time:now,walk:0,work:0,graze:0,action:l.action,phase:e.id*.37};creatureAnimation.set(e,p);}const dt=Math.max(0,Math.min(.1,now-p.time));p.time=now;const blend=1-Math.exp(-dt*12),speed=Math.hypot(m.vx,m.vy),working=['chop','harvest','plant','build','mine','fish','craft'].includes(l.action)&&speed<.18; p.walk+=(Math.min(1,speed/.9)-p.walk)*blend;p.work+=((working?1:0)-p.work)*blend;p.graze+=((l.action==='graze'?1:0)-p.graze)*blend;if(working)p.action=l.action;p.phase+=dt*(p.action==='fish'?1.7:p.action==='harvest'||p.action==='plant'?3.5:4.4);return p;}
function drawLaborTool(e,p){if(p.work<.01)return;const facing=motionFor(e).facing||1,t=p.phase%(Math.PI*2)/(Math.PI*2),ease=x=>x*x*(3-2*x);const strike=t<.62?ease(t/.62):1-ease((t-.62)/.38),fishing=p.action==='fish',harvesting=['harvest','plant'].includes(p.action),angle=fishing?-.45+Math.sin(p.phase)*.08:harvesting?-.15+Math.sin(p.phase)*.36:-1.15+strike*1.7;ctx.save();ctx.globalAlpha*=p.work;ctx.translate(e.x+facing*.22,e.y-.38);ctx.scale(facing,1);ctx.rotate(angle);ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#e9bc93';ctx.lineWidth=.10;ctx.beginPath();ctx.moveTo(-.05,.12);ctx.lineTo(.13,.03);ctx.lineTo(.23,-.10);ctx.stroke();ctx.strokeStyle='#846044';ctx.lineWidth=.055;ctx.beginPath();ctx.moveTo(.15,.17);ctx.lineTo(.15,-.46);ctx.stroke();ctx.fillStyle='#bfd5d4';if(fishing){ctx.strokeStyle='#b6d2d6';ctx.lineWidth=.018;ctx.beginPath();ctx.moveTo(.15,-.46);ctx.quadraticCurveTo(.8,-.3,.85,.43);ctx.stroke();}else if(p.action==='plant'){ctx.fillStyle='#91b45d';ctx.beginPath();ctx.ellipse(.16,-.41,.11,.07,.4,0,Math.PI*2);ctx.fill();}else if(harvesting){ctx.strokeStyle='#d5dfca';ctx.lineWidth=.06;ctx.beginPath();ctx.arc(.18,-.42,.17,-2.8,-.2);ctx.stroke();}else{ctx.fillRect(p.action==='chop'?.12:.03,-.5,p.action==='chop'?.23:.25,.12);}ctx.restore();}
drawCreature=function(e,bob){if(isResidentIndoors(e))return;const p=animationPose(e),wave=Math.sin(motionFor(e).steps*7+e.id),breath=Math.sin(animationTime()*1.6+e.id)*.008*(1-p.walk),workDip=p.work*(1-Math.cos(p.phase))*.012;ctx.save();ctx.translate(e.x,e.y+.25);ctx.rotate(e.kind==='human'?p.work*Math.sin(p.phase)*.018:p.graze*(.035+Math.sin(p.phase)*.012));ctx.scale(1+wave*p.walk*.009,1-wave*p.walk*.009+breath);ctx.translate(-e.x,-e.y-.25);livingOld.drawCreature(e,-Math.abs(wave)*.023*p.walk+workDip);ctx.restore();if(e.kind!=='human')return;drawLaborTool(e,p);const l=lifeFor(e);if(l.load>0){const f=motionFor(e).facing||1;ctx.save();ctx.translate(e.x-f*.35,e.y-.30+Math.sin(motionFor(e).steps*7+e.id)*p.walk*.017);ctx.rotate(-f*.15);ctx.fillStyle=l.loadType==='wood'?'#ab7c49':'#cab072';ctx.strokeStyle='#6e5337';ctx.lineWidth=.025;ctx.beginPath();ctx.roundRect(-.16,-.19,.30,.30,.04);ctx.fill();ctx.stroke();ctx.strokeStyle='#eee0b0';ctx.beginPath();ctx.moveTo(-.17,-.06);ctx.lineTo(.14,-.06);ctx.stroke();ctx.restore();}};
draw=function(){livingOld.draw();const s=base*zoom;ctx.save();ctx.translate((cw-W*s)/2+panX,(ch-H*s)/2+panY);ctx.scale(s,s);ctx.font='bold .8px Segoe UI';ctx.textAlign='center';const sleepCounts=new Map();for(const e of humans())if(isResidentIndoors(e)&&e.life.action==='sleep')sleepCounts.set(e.life.homeId,(sleepCounts.get(e.life.homeId)||0)+1);for(const h of houses){if(typeof ambianceVisible==='function'&&!ambianceVisible(h.x,h.y))continue;const sleepers=sleepCounts.get(h.id)||0;if(sleepers){ctx.fillStyle='#cbe4fa';ctx.fillText('☾ '+sleepers,h.x,h.y-2.8);}}for(const v of villages)if(v.housePlan){const p=v.housePlan;ctx.strokeStyle='#d6b080';ctx.lineWidth=.12;ctx.strokeRect(p.x-1,p.y-1,2,1.5);ctx.fillStyle='#d6b080';ctx.fillRect(p.x-.8,p.y-.8,1.6*p.progress,.12);}ctx.restore();};
showSelection=function(id){livingOld.selection(id);const e=entities.find(e=>e.id===id);if(!e)return;const l=lifeFor(e),p=document.createElement('p');p.textContent=e.kind==='human'?(isResidentIndoors(e)?'🏠 Đang ở trong nhà · '+(l.action==='sleep'?'Ngủ':'Nghỉ'):'Sinh hoạt: '+(purposeNames[l.action]||purposeNames[mindFor(e).type]||'Đi lại'))+' · Tay nghề '+Math.floor(l.skill)+'%'+(l.load>0?' · Mang '+l.load.toFixed(1)+' '+(l.loadType==='wood'?'gỗ':'thức ăn'):''):'💧 Nước '+Math.round(l.thirst)+'% · Thể lực '+Math.round(l.energy)+'%';$('selection').append(p);};
const livingAdvance=advanceCreature;
const livingPerson=drawPerson;
drawPerson=function(e,bob){let img=sprite,n=e.village===2?5:4,columns=4,size=1.35;if(['elf','dwarf','orc'].includes(e.race)){img=civilSprite;n={elf:0,dwarf:1,orc:2}[e.race];columns=2;size=e.race==='orc'?1.8:1.55;}else if(['goblin','beastkin'].includes(e.race)){img=economySprite;n=e.race==='goblin'?0:1;size=1.7;}const art=typeof prepareAtlas==='function'?prepareAtlas(img,columns):null;if(!art){livingPerson(e,bob);return;}if(e.age<16)size*=.68+e.age/16*.32;const p=animationPose(e),wave=Math.sin(motionFor(e).steps*7+e.id),x=e.x-size/2,y=e.y+bob-size*.72,sx=n%columns*64,sy=Math.floor(n/columns)*64;ctx.save();ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';// Overlapping narrow bands bend continuously instead of separating legs from the body.
for(let row=0;row<64;row+=8){const h=Math.min(9,64-row),lower=Math.max(0,(row-32)/32),shift=wave*p.walk*.022*lower*lower;ctx.drawImage(art.sheet,sx,sy+row,64,h,x+shift,y+row/64*size,size,h/64*size);}ctx.restore();};
advanceCreature=function(e,dt){if(isResidentIndoors(e))return;livingAdvance(e,dt);if(Math.hypot(motionFor(e).vx,motionFor(e).vy)<.15)return;const peers=around(e,.5,p=>!isResidentIndoors(p)&&p.kind===e.kind).slice(0,5);let dx=0,dy=0;for(const p of peers){const x=e.x-p.x,y=e.y-p.y,d=Math.hypot(x,y);const a=d>.01?Math.atan2(y,x):e.id<p.id?0:Math.PI;const push=(.5-d)*dt*.8;dx+=Math.cos(a)*push;dy+=Math.sin(a)*push;}if(walkable(e.x+dx,e.y+dy)&&!grid[idx(e.x+dx,e.y+dy)].fire){e.x+=dx;e.y+=dy;}if(e.kind==='human'&&e.village&&!['flee','sleep'].includes(lifeFor(e).action)){const i=idx(e.x,e.y),prior=lastFootTile.get(e);if(prior!==i){lastFootTile.set(e,i);const t=grid[i];if(t.t===1&&t.obj===-1&&!t.road){const count=(footTraffic.get(i)||0)+1;footTraffic.set(i,count);if(count>=12){t.road=true;footTraffic.delete(i);mapDirty=true;}}}}};
resetLiving();
window.mamWorld={...window.mamWorld,newWorld:(...a)=>newWorld(...a),simulate:dt=>simulate(dt),snapshot:()=>snapshot(),restore:d=>restore(d),getLiving:()=>({indoors:humans().filter(isResidentIndoors).length,sleeping:humans().filter(e=>isResidentIndoors(e)&&e.life.action==='sleep').length,logging:humans().filter(e=>lifeFor(e).action==='chop').length,carrying:humans().filter(e=>lifeFor(e).load>0).length,homesUnderConstruction:villages.filter(v=>v.housePlan).length,residents:humans().map(e=>({id:e.id,name:e.name,action:lifeFor(e).action,homeId:e.life.homeId,inside:isResidentIndoors(e),skill:e.life.skill}))})};

if(document.modelContext?.registerTool)try{Promise.resolve(document.modelContext.registerTool({name:'read_world_living',description:'Read residents physically indoors, logging, carrying supplies, their assigned homes and construction projects.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.mamWorld.getLiving()})).catch(()=>{});}catch{}
